// lib/questioning/engine/question_engine.dart
//
// ★ 共通入口：practice/mock_exam からは原則ここだけを呼ぶ（パターンA）
// - UI を変えずに QuestionService 直呼びを隠す
// - まずは戻り値を Map のままにして既存UIを壊さない
// - 将来（パターンB）で QuestionService を分割し、GeneratedQuestion を返すように進化させる

import '../models/question_spec.dart';
import '../services/question_service.dart';

class QuestionEngine {
  QuestionEngine._();
  static final QuestionEngine instance = QuestionEngine._();

  /// 既存 UI の互換性のため Map を返す。
  /// 将来は GeneratedQuestion を返す方向へ（パターンB）。
  Future<Map<String, dynamic>> generate(QuestionSpec spec) async {
    return QuestionService.fetchQuestion(
      difficulty: spec.difficulty,
      domain: spec.domain,
      major: spec.major,
      mid: spec.mid,
      scenarioAspect: spec.scenarioAspectCode,
    );
  }
}

// lib/questioning/models/category_models.dart

/// 分野（Domain）> 大項目（Major）> 中項目（Mid）> トピック（Topic）
/// のツリー構造を型で表現するためのモデル。

class Topic {
  final String id;     // 内部ID（=既存のラベルでもOK）
  final String label;  // 表示名
  const Topic({required this.id, required this.label});
}

class MidCategory {
  final String id;
  final String label;
  final List<Topic> topics;
  const MidCategory({
    required this.id,
    required this.label,
    required this.topics,
  });
}

class MajorCategory {
  final String id;
  final String label;
  final List<MidCategory> mids;
  const MajorCategory({
    required this.id,
    required this.label,
    required this.mids,
  });
}

class DomainCategory {
  final String id;       // 例: '成人看護学' / '必修'
  final String label;    // 表示名
  final List<MajorCategory> majors;
  const DomainCategory({
    required this.id,
    required this.label,
    required this.majors,
  });
}

/// 分野〜トピックを指すパス（履歴保存・選定結果の受け渡しに便利）
class CategoryPath {
  final String domainId;
  final String majorId;
  final String? midId;
  final String? topicId;
  const CategoryPath({
    required this.domainId,
    required this.majorId,
    this.midId,
    this.topicId,
  });

  CategoryPath copyWith({
    String? domainId,
    String? majorId,
    String? midId,
    String? topicId,
  }) {
    return CategoryPath(
      domainId: domainId ?? this.domainId,
      majorId: majorId ?? this.majorId,
      midId: midId ?? this.midId,
      topicId: topicId ?? this.topicId,
    );
  }
}

/// （任意）状況設定の観点コードを型で扱うためのenum
enum ScenarioAspect { A, B, C, D, E }

extension ScenarioAspectX on ScenarioAspect {
  String get code => toString().split('.').last; // 'A'..'E'
  static ScenarioAspect? fromCode(String? c) {
    if (c == null) return null;
    switch (c) {
      case 'A': return ScenarioAspect.A;
      case 'B': return ScenarioAspect.B;
      case 'C': return ScenarioAspect.C;
      case 'D': return ScenarioAspect.D;
      case 'E': return ScenarioAspect.E;
    }
    return null;
  }
}

// lib/questioning/models/generated_question.dart

/// GeneratedQuestion
///
/// LLM によって生成された問題データを、型安全に扱うための
/// DTO（Data Transfer Object / データ受け渡し用オブジェクト）。
///
/// 現在の NurAI では、practice / mock_exam / 一部互換処理との整合のため、
/// QuestionService の主な返り値はまだ `Map<String, dynamic>` を使用している。
/// そのため、このクラスは現時点では
/// 「将来のDTO本線化に向けた準備用モデル」という位置づけである。
///
/// 想定している将来構造は以下のとおり。
///
/// ResponseParser
///   ↓
/// GeneratedQuestion
///   ↓
/// QuestionService / QuestionEngine
///   ↓
/// practice / mock_exam / その他UI層
///
/// DTO化により期待できること:
/// - 型安全性の向上
/// - IDE補完の強化
/// - 保守性の向上
/// - 問題データ構造の明確化
///
/// ただし現段階では、UI層や既存互換処理が Map ベースで動作しているため、
/// 全面移行はまだ行っていない。
///
/// そのためこのクラスは、今後のリファクタリング時に
/// questioning 内部から段階的に DTO 化を進めるための基盤として保持する。
class GeneratedQuestion {
  final String question;
  final Map<String, String> choices;
  final List<String> correctAnswers;
  final String questionKind;
  final String explanation;
  final Map<String, String>? rationales;
  final String sourceType;

  const GeneratedQuestion({
    required this.question,
    required this.choices,
    required this.correctAnswers,
    required this.questionKind,
    required this.explanation,
    this.rationales,
    required this.sourceType,
  });

  Map<String, dynamic> toJson() => {
    'question': question,
    'choices': choices,
    'correctAnswers': correctAnswers,
    'questionKind': questionKind,
    'explanation': explanation,
    'rationales': rationales,
    'sourceType': sourceType,
  };
}

// lib/questioning/models/question_spec.dart
//
// 出題生成リクエスト（DTO）
// ※ Ver5 移行フェーズ（パターンA）では、まず UI から QuestionService を隠すための最小DTO。
// ※ choiceMode/確率/4択5択/複数選択などは SettingsService と QuestionService 側で決定する方針のため、ここでは持たない。

class QuestionSpec {
  final String difficulty;
  final String domain;
  final String major;
  final String? mid;

  /// 状況設定の観点コード（例: 'jokyo_XXXX' など）
  /// practice/mock_exam 共通で “code” を渡す想定のためこの名前に統一。
  final String? scenarioAspectCode;

  const QuestionSpec({
    required this.difficulty,
    required this.domain,
    required this.major,
    this.mid,
    this.scenarioAspectCode,
  });

  @override
  String toString() {
    return 'QuestionSpec(difficulty=$difficulty, domain=$domain, major=$major, mid=$mid, scenarioAspectCode=$scenarioAspectCode)';
  }
}

// lib/questioning/repositories/category_repository.dart

import '../models/category_models.dart';

// 既存のデータ定義をそのまま利用
import '../../data/categories.dart';          // domains, majorsOf(), midsOf(), topicsOf()
import '../../data/hisshu_categories.dart';   // kHisshuCategory, hisshuMajors(), hisshuMidsOf(), hisshuTopicsOf()

/// 既存の関数群（majorsOf/midsOf/topicsOf 等）を“型付きツリー”に変換するリポジトリ。
/// まずは追加だけ。徐々にこちらの型へ置き換えていけます。
class CategoryRepository {
  /// 一般/状況設定の分野ツリーを構築（ドメイン名で指定）
  static DomainCategory buildGeneralDomainTree(String domain) {
    final majorNames = majorsOf(domain);
    final majors = majorNames.map((maj) {
      final midNames = midsOf(domain, maj);
      final mids = midNames.map((mid) {
        final topicNames = topicsOf(domain, maj, mid);
        final topics = topicNames
            .map((t) => Topic(id: t, label: t))
            .toList(growable: false);
        return MidCategory(id: mid, label: mid, topics: topics);
      }).toList(growable: false);
      return MajorCategory(id: maj, label: maj, mids: mids);
    }).toList(growable: false);

    return DomainCategory(id: domain, label: domain, majors: majors);
  }

  /// 必修ツリーを構築（ドメインは kHisshuCategory 固定）
  static DomainCategory buildHisshuTree() {
    final majorNames = hisshuMajors();
    final majors = majorNames.map((maj) {
      final midNames = hisshuMidsOf(maj);
      final mids = midNames.map((mid) {
        final topicNames = hisshuTopicsOf(maj, mid);
        final topics = topicNames
            .map((t) => Topic(id: t, label: t))
            .toList(growable: false);
        return MidCategory(id: mid, label: mid, topics: topics);
      }).toList(growable: false);
      return MajorCategory(id: maj, label: maj, mids: mids);
    }).toList(growable: false);

    return DomainCategory(id: kHisshuCategory, label: kHisshuCategory, majors: majors);
  }

  // ========== 以下は“移行を楽にする”ための薄いFacade（今のAPIを保ったまま裏で型へ） ==========

  static List<String> generalDomains() => domains;

  static List<String> generalMajorsOf(String domain) => majorsOf(domain);

  static List<String> generalMidsOf(String domain, String major) =>
      midsOf(domain, major);

  static List<String> generalTopicsOf(String domain, String major, String mid) =>
      topicsOf(domain, major, mid);

  static List<String> hisshuMajorItems() => hisshuMajors();

  static List<String> hisshuMids(String major) => hisshuMidsOf(major);

  static List<String> hisshuTopics(String major, String mid) =>
      hisshuTopicsOf(major, mid);
}

// lib/questioning/services/openai_chat_client.dart
import 'dart:convert';
import 'dart:typed_data';

import 'package:http/http.dart' as http;

class OpenAiChatClient {
  OpenAiChatClient({
    http.Client? httpClient,
    String? endpoint,
  })  : _http = httpClient ?? http.Client(),
        _endpoint = endpoint ?? 'https://api.openai.com/v1/chat/completions';

  final http.Client _http;
  final String _endpoint;

  Future<OpenAiChatResult> createJsonObjectCompletion({
    required String apiKey,
    required String model,
    required String system,
    required String user,
    double temperature = 0.4,
  }) async {
    final reqMap = {
      'model': model,
      'temperature': temperature,
      'response_format': {'type': 'json_object'},
      'messages': [
        {'role': 'system', 'content': system},
        {'role': 'user', 'content': user},
      ],
    };

    final reqBody = jsonEncode(reqMap);

    final res = await _http.post(
      Uri.parse(_endpoint),
      headers: {
        'Content-Type': 'application/json',
        'Authorization': 'Bearer $apiKey',
      },
      body: reqBody,
    );

    final Uint8List bytes = res.bodyBytes;
    final decodedBody = utf8.decode(bytes);

    if (res.statusCode < 200 || res.statusCode >= 300) {
      throw OpenAiHttpException(
        statusCode: res.statusCode,
        body: decodedBody,
      );
    }

    final Map<String, dynamic> root = jsonDecode(decodedBody) as Map<String, dynamic>;
    final List choicesRoot = (root['choices'] as List? ?? const []);
    final String content = choicesRoot.isNotEmpty
        ? (choicesRoot.first['message']?['content']?.toString() ?? '')
        : '';

    return OpenAiChatResult(
      requestBody: reqBody,
      responseBody: decodedBody,
      content: content,
    );
  }
}

class OpenAiChatResult {
  final String requestBody;
  final String responseBody;
  final String content;
  OpenAiChatResult({
    required this.requestBody,
    required this.responseBody,
    required this.content,
  });
}

class OpenAiHttpException implements Exception {
  final int statusCode;
  final String body;
  OpenAiHttpException({required this.statusCode, required this.body});

  @override
  String toString() => 'OpenAI request failed ($statusCode): $body';
}

// lib/questioning/services/prompt_builder.dart

/// OpenAI へ送るプロンプト（system / user）の組み立てを担当するユーティリティ。
class PromptBuilder {
  /// system プロンプト（固定方針＋ハード制約）
  ///
  /// - 必ず JSON オブジェクトのみを返す（前後に説明文やコードフェンスを付けない）
  /// - `questionKind` は desiredKind と一致させる
  /// - 選択肢数は desiredChoiceCount 個「ちょうど」
  /// - 正答数は requiredCorrectCount と一致（single=1 / multiple=2）
  /// - "select_incorrect" のときは、`correctAnswers` に「誤っている選択肢」のラベルを入れる
  /// - 医学・看護学的に整合した正誤になるよう、自己チェックを行う
  ///
  /// 出力スキーマ:
  ///   {
  ///     "question": string,
  ///     "choices": { "A": string, "B": string, ... },   // A..D または A..E
  ///     "correctAnswers": [ "A", ... ],                  // ラベル配列（1 or 2）
  ///     "questionKind": "single" | "multiple" | "select_incorrect",
  ///     "explanation": string,
  ///     "rationales": { "A": string, "B": string, ... } // 任意
  ///   }
  static String buildSystemPrompt({
    String desiredKind = 'single',
    int desiredChoiceCount = 4,
    int requiredCorrectCount = 1,
  }) {
    return [
      'あなたは日本の看護師国家試験の出題委員です。',
      '厚労省の出題基準に準拠し、日本語として自然で学術的に正確な択一式問題を作成します。',
      '出力は必ず JSON オブジェクトのみ（前後に余計な文字やコードフェンスを含めない）。',

      '',
      '【厳守すべき形式制約】',
      '- "questionKind" は必ず "$desiredKind" とする。',
      '- 選択肢 "choices" は { "A": "...", "B": "...", ... } の連想配列形式で、キーは A から始まる昇順 (A〜${desiredChoiceCount == 5 ? 'E' : 'D'})。',
      '- 選択肢の個数は ちょうど $desiredChoiceCount 個にする（多すぎ/少なすぎは禁止）。',
      '- "correctAnswers" は ["A", ...] の形で、要素数は $requiredCorrectCount 個に一致させる。',
      '- single のときは正答は 1 個、multiple のときは正答は 2 個に固定。',
      '- "select_incorrect" のときは、"correctAnswers" には「誤っている選択肢」のラベルだけを入れる（正しい選択肢のラベルは絶対に含めない）。',

      '',
      '【内容上の厳格な条件】',
      '- 医学・看護学的に明確な正誤が判断できるテーマを扱う。',
      '- 正しい選択肢は、解説や rationales でも「正しい」「妥当」など一貫して肯定される内容にする。',
      '- 誤っている選択肢は、解説や rationales でも「誤り」「不適切」など一貫して否定される内容にする。',
      '- "select_incorrect" のとき:',
      '  - 選択肢のうち $requiredCorrectCount 個だけ明確に誤った記述にし、それ以外は明確に正しい記述にする。',
      '  - "correctAnswers" には、その誤った選択肢のラベルだけを列挙する。',
      '- "multiple" のとき:',
      '  - 正答の選択肢同士は、すべて正しい内容で互いに矛盾しないようにする。',
      '  - 誤答の選択肢は、明確な誤りを含む記述にする。',
      '- "single" のとき:',
      '  - 正答は 1 つだけが明らかに正しく、他は明らかに誤りになるようにする。',

      '',
      '【自己チェック】',
      '- 出力する前に、次のチェックを必ず行うこと:',
      '  1) "correctAnswers" に含まれるラベルの選択肢が、本当に指定の意味で正しい／誤っているか（問題文の指示と矛盾しないか）。',
      '  2) "explanation" と "rationales" が、"correctAnswers" に指定したラベルと論理的に矛盾していないか。',
      '  3) "select_incorrect" の場合、"correctAnswers" の各ラベルの文章が、本当に誤った記述になっているか。',

      '',
      '【禁止事項】',
      '- JSON 以外の文字、注釈、コードフェンス、整形エラー。',
      '- 指定個数と異なる選択肢数や正答数。',
      '- 正しいはずの選択肢を「誤答」として "correctAnswers" に含めること。',
      '- 誤っているはずの選択肢を「正答」として扱うこと。',

      '',
      '【出力スキーマ】',
      '{',
      '  "question": string,',
      '  "choices": { "A": string, "B": string, "C": string, "D": string' +
          (desiredChoiceCount == 5 ? ', "E": string' : '') +
          ' },',
      '  "correctAnswers": [ "A"' + (requiredCorrectCount == 2 ? ', "B"' : '') + ' ],',
      '  "questionKind": "single" | "multiple" | "select_incorrect",',
      '  "explanation": string,',
      '  "rationales": { "A": string, "B": string, "C": string, "D": string' +
          (desiredChoiceCount == 5 ? ', "E": string' : '') +
          ' }',
      '}',
    ].join('\n');
  }

  /// user プロンプト（出題条件）
  static String buildUserPrompt({
    required String difficulty,     // 必修問題 / 一般問題 / 状況設定問題
    required String domain,         // 例：人体の構造と機能
    required String major,          // 例：循環器系
    String? mid,
    String? topic,
    String? scenarioAspect,
    String desiredKind = 'single',  // single / multiple / select_incorrect
    int desiredChoiceCount = 4,     // 4 or 5
    int requiredCorrectCount = 1,   // single=1, multiple=2 など
  }) {
    final b = StringBuffer();
    b.writeln('出題形式: $difficulty');
    b.writeln('分野: $domain');
    b.writeln('大項目: $major');
    if (mid != null && mid.isNotEmpty) b.writeln('中項目: $mid');
    if (topic != null && topic.isNotEmpty) b.writeln('トピック: $topic');
    if (scenarioAspect != null && scenarioAspect.isNotEmpty) {
      b.writeln('状況設定の観点: $scenarioAspect');
    }
    b.writeln('');

    b.writeln('【問題生成の仕様】');
    b.writeln('- questionKind は "$desiredKind" に固定する。');
    b.writeln('- 選択肢は $desiredChoiceCount 個に固定（A..' +
        (desiredChoiceCount == 5 ? 'E' : 'D') + '）。');
    b.writeln('- 正答数は $requiredCorrectCount 個に固定する。');
    if (desiredKind == 'select_incorrect') {
      b.writeln('- select_incorrect の場合、"correctAnswers" は「誤っている選択肢」のラベルだけを列挙する（正しい選択肢は絶対に含めない）。');
      b.writeln('- 誤っている選択肢は、明確に誤りと分かる内容にし、他の選択肢は明確に正しい内容にする。');
    } else {
      b.writeln('- single/multiple の場合、"correctAnswers" は内容的に正しい選択肢のラベルだけを列挙する。');
      b.writeln('- 誤答選択肢には、事実と異なる、もしくは不適切な記述を入れる。');
    }
    b.writeln('- 出力は必ず JSON オブジェクトのみ。');
    b.writeln('- 各選択肢は重複や曖昧さがないように明確に作成する。');
    b.writeln('- 解説は根拠を簡潔に示す。可能なら各選択肢の理由 (rationales) を付与する。');

    b.writeln('');
    b.writeln('【自己チェック】');
    b.writeln('- 出力前に、次の点を必ず確認してから JSON を返すこと:');
    b.writeln('  1) 問題文の指示（「正しいものを選べ」「誤っているものを選べ」など）と、"correctAnswers" の意味が一致しているか。');
    b.writeln('  2) "correctAnswers" に含まれるラベルの文章が、解説・rationales の内容と矛盾していないか。');

    // =========================
    // ここから「状況設定問題」専用の追加要件
    // =========================
    if (difficulty == '状況設定問題') {
      b.writeln('');
      b.writeln('【状況設定問題としての追加要件】');
      b.writeln('- 問題文全体は「状況設定文＋設問」という構成にする。');
      b.writeln('- "question" フィールドのテキストは、次の構造を持つ 1 本の文章とする:');
      b.writeln('  1) 冒頭に「次の文を読み問題に答えよ。」などの指示文を置く。');
      b.writeln('  2) その後に、患者や家族などの背景を説明する状況設定文を 3〜6 文程度書く。');
      b.writeln('     - 年齢（例：◯歳の男性／女性）');
      b.writeln('     - 職業や生活背景（例：会社員、一人暮らし、夫と二人暮らし など）');
      b.writeln('     - 既往歴や治療歴、家族構成、生活上の困りごとなど');
      b.writeln('     - 発症のきっかけや現在の症状、受診の経緯 など');
      b.writeln('  3) 最後に「問題1」または「このとき看護師の対応として最も適切なのはどれか。」など、国試の設問らしい一文で締める。');
      b.writeln('- 文章量の目安は全体で日本語 300〜600字程度とし、短すぎず長すぎない分量にする。');
      b.writeln('- 会話文だけにならないようにし、地の文（叙述）と会話をバランスよく用いる。');
      b.writeln('- 時系列の流れ（受診前 → 受診時 → 受診後 など）がある程度わかるように記述する。');
      b.writeln('- 看護師が判断・対応を問われる文脈（観察、情報収集、家族への支援、多職種連携など）を明確に示す。');
      b.writeln('- 実際の看護師国家試験の状況設定問題の雰囲気に近づける。');
      b.writeln('- 設問の主語は「看護師」や「看護管理者」などを用い、国家試験らしい問い方にする。');
    }

    return b.toString();
  }
}

// lib/questioning/services/question_generation_options_resolver.dart
import 'dart:math';

import '../../features/settings/services/settings_service.dart';

class QuestionGenerationOptions {
  final String choiceMode;
  final int probFiveChoice;
  final int probMultiple;
  final int probIncorrect;
  final int desiredChoiceCount;
  final String desiredKind;
  final int requiredCorrectCount;

  const QuestionGenerationOptions({
    required this.choiceMode,
    required this.probFiveChoice,
    required this.probMultiple,
    required this.probIncorrect,
    required this.desiredChoiceCount,
    required this.desiredKind,
    required this.requiredCorrectCount,
  });
}

class QuestionGenerationOptionsResolver {
  const QuestionGenerationOptionsResolver._();

  static Future<QuestionGenerationOptions> resolve() async {
    final choiceMode = await SettingsService.getChoiceMode() ?? 'auto';
    final probFiveChoice =
        (await SettingsService.getFiveChoiceProbability()) ?? 0;
    final probMultiple =
        (await SettingsService.getMultipleKindProbability()) ?? 0;
    final probIncorrect =
        (await SettingsService.getIncorrectKindProbability()) ?? 0;

    final rand = Random(DateTime.now().microsecondsSinceEpoch);

    final int desiredChoiceCount;
    switch (choiceMode) {
      case 'force4':
        desiredChoiceCount = 4;
        break;
      case 'force5':
        desiredChoiceCount = 5;
        break;
      default:
        desiredChoiceCount = rand.nextInt(100) < probFiveChoice ? 5 : 4;
        break;
    }

    final bool wantMultiple = rand.nextInt(100) < probMultiple;
    final bool wantIncorrect = rand.nextInt(100) < probIncorrect;

    final String desiredKind;
    final int requiredCorrectCount;

    if (wantIncorrect && wantMultiple) {
      desiredKind = 'select_incorrect';
      requiredCorrectCount = 2;
    } else if (wantIncorrect) {
      desiredKind = 'select_incorrect';
      requiredCorrectCount = 1;
    } else if (wantMultiple) {
      desiredKind = 'multiple';
      requiredCorrectCount = 2;
    } else {
      desiredKind = 'single';
      requiredCorrectCount = 1;
    }

    return QuestionGenerationOptions(
      choiceMode: choiceMode,
      probFiveChoice: probFiveChoice,
      probMultiple: probMultiple,
      probIncorrect: probIncorrect,
      desiredChoiceCount: desiredChoiceCount,
      desiredKind: desiredKind,
      requiredCorrectCount: requiredCorrectCount,
    );
  }
}

// lib/questioning/services/question_post_processor.dart
import 'dart:math';

class QuestionPostProcessor {
  const QuestionPostProcessor._();

  static Map<String, dynamic> process({
    required Map<String, dynamic> parsed,
    required String desiredKind,
    required int requiredCorrectCount,
  }) {
    final out = Map<String, dynamic>.from(parsed);

    final Map<String, String>? outChoices =
    (out['choices'] as Map?)?.map((k, v) => MapEntry('$k', '$v'));

    final List<String> outCorrect = ((out['correctAnswers'] as List?) ?? const [])
        .map((e) => e.toString())
        .toList();

    if (outChoices == null) {
      return out;
    }

    // 1) 正答が choices に含まれない場合の安全弁
    final present = outChoices.keys.toSet();
    final filtered = outCorrect.where(present.contains).toList();
    out['correctAnswers'] = filtered.isNotEmpty
        ? filtered
        : (outChoices.isNotEmpty ? [outChoices.keys.first] : []);

    // 2) 問題文に「nつ選んでください」を付与
    final isMulti =
        desiredKind == 'multiple' || desiredKind == 'select_incorrect';
    final q = (out['question'] as String? ?? '').trim();
    out['question'] = _ensureCountInstruction(
      q,
      isMulti: isMulti,
      requiredCorrectCount: requiredCorrectCount,
    );

    // 3) 正答位置を完全ランダム化（毎回シャッフル）
    final remapped = _remapChoicesRandom(
      originalChoices: outChoices,
      originalCorrectLabels: (out['correctAnswers'] as List).cast<String>(),
      originalRationales: (out['rationales'] as Map?)?.cast<String, String>(),
    );

    out['choices'] = remapped.choices;
    out['correctAnswers'] = remapped.corrects;
    if (remapped.rationales != null) {
      out['rationales'] = remapped.rationales;
    }

    return out;
  }

  static String ensureCountInstructionForTest(
      String q, {
        required bool isMulti,
        required int requiredCorrectCount,
      }) {
    return _ensureCountInstruction(
      q,
      isMulti: isMulti,
      requiredCorrectCount: requiredCorrectCount,
    );
  }

  static String _ensureCountInstruction(
      String q, {
        required bool isMulti,
        required int requiredCorrectCount,
      }) {
    if (!isMulti || requiredCorrectCount <= 1) return q;

    final already =
    RegExp(r'[0-9一二三四五六七八九十]+\s*つ\s*選んでください').hasMatch(q);
    if (already) return q;

    return '$q ${requiredCorrectCount}つ選んでください';
  }

  static _RemapResult _remapChoicesRandom({
    required Map<String, String> originalChoices,
    required List<String> originalCorrectLabels,
    Map<String, String>? originalRationales,
  }) {
    final labels =
    ['A', 'B', 'C', 'D', 'E'].where(originalChoices.containsKey).toList();
    final n = labels.length;
    if (n <= 1) {
      return _RemapResult(
        Map<String, String>.from(originalChoices),
        List<String>.from(originalCorrectLabels),
        originalRationales == null
            ? null
            : Map<String, String>.from(originalRationales),
      );
    }

    final rng = Random(DateTime.now().microsecondsSinceEpoch);
    final entries = <MapEntry<String, String>>[
      for (final k in labels) MapEntry(k, originalChoices[k]!)
    ]..shuffle(rng);

    final originalCorrectSet = originalCorrectLabels.toSet();

    final newChoices = <String, String>{};
    final newCorrects = <String>[];
    final Map<String, String>? newRationales =
    originalRationales != null ? <String, String>{} : null;

    for (var i = 0; i < entries.length; i++) {
      final newLabel = String.fromCharCode('A'.codeUnitAt(0) + i);
      final e = entries[i];

      newChoices[newLabel] = e.value;

      if (originalCorrectSet.contains(e.key)) {
        newCorrects.add(newLabel);
      }

      if (newRationales != null) {
        final r = originalRationales![e.key];
        if (r != null && r.trim().isNotEmpty) {
          newRationales[newLabel] = r;
        }
      }
    }

    return _RemapResult(newChoices, newCorrects, newRationales);
  }
}

class _RemapResult {
  final Map<String, String> choices;
  final List<String> corrects;
  final Map<String, String>? rationales;

  const _RemapResult(this.choices, this.corrects, this.rationales);
}

// lib/questioning/services/question_service.dart
//
// QuestionService
// ================================
//
// ■ 役割
// Questioningレイヤーにおける「問題生成オーケストレーター」。
// UI層や QuestionEngine から呼ばれ、問題生成フロー全体を調停する。
// 自身は具体的ロジックをほぼ持たず、各専用サービスへ委譲する。
//
// ■ 現在の責務
// - APIキー / モデル取得
// - 出題形式決定（resolver呼び出し）
// - mid / topic 決定（resolver呼び出し）
// - prompt生成
// - OpenAI呼び出し
// - LLMレスポンスのパース
// - 最終安全化処理
// - Map形式 or NuraiQuestion形式で返却
//
// ■ 実際の処理担当
//
// 出題形式決定
//   → question_generation_options_resolver.dart
//
// mid / topic 決定
//   → question_topic_resolver.dart
//
// prompt生成
//   → prompt_builder.dart
//
// OpenAI HTTP
//   → openai_chat_client.dart
//
// LLMレスポンス整形
//   → response_parser.dart
//
// 最終安全化
//   → question_post_processor.dart
//
// ■ 将来構造
// QuestionEngine が生成司令塔になり、
// QuestionService は「LLM生成サービス」としてさらに薄くなる想定。
//

import 'dart:convert';

import 'package:flutter/foundation.dart';

import '../../features/past_exam/models/past_exam_question.dart';
import '../../features/settings/services/settings_service.dart';

import 'openai_chat_client.dart';
import 'prompt_builder.dart';
import 'question_generation_options_resolver.dart';
import 'question_post_processor.dart';
import 'question_topic_resolver.dart';
import 'response_parser.dart';

class QuestionService {
  static final OpenAiChatClient _chatClient = OpenAiChatClient();

  /// PastExam(NuraiQuestion)向け互換ラッパ
  ///
  /// LLM生成結果(Map)を NuraiQuestion へ変換する。
  /// practice / mock / past_exam 互換維持のため存在。
  static Future<NuraiQuestion> fetchNuraiQuestion({
    required String difficulty,
    required String domain,
    required String major,
    String? mid,
    String? scenarioAspect,
  }) async {
    final raw = await fetchQuestion(
      difficulty: difficulty,
      domain: domain,
      major: major,
      mid: mid,
      scenarioAspect: scenarioAspect,
    );

    final choices =
    (raw['choices'] as Map? ?? const {}).map((k, v) => MapEntry('$k', '$v'));

    final correctLabels = ((raw['correctAnswers'] as List?) ?? const [])
        .map((e) => e.toString())
        .toList();

    final rationales =
    (raw['rationales'] as Map?)?.map((k, v) => MapEntry('$k', '$v'));

    final questionText =
    (raw['question'] ?? raw['questionText'] ?? '').toString();
    final kind = (raw['questionKind'] ?? 'single').toString();

    final requiredCorrectCount = (raw['requiredCorrectCount'] is int)
        ? raw['requiredCorrectCount'] as int
        : correctLabels.length.clamp(1, choices.length);

    final sourceTag = (raw['sourceTag']?.toString().trim() ?? '');
    final fixedSourceTag =
    sourceTag.isNotEmpty ? sourceTag : 'ai:${DateTime.now().millisecondsSinceEpoch}';

    final imagePath = raw['imagePath']?.toString();
    final imageRequired = raw['imageRequired'] == true;

    return NuraiQuestion(
      questionText: questionText,
      backgroundText: raw['backgroundText']?.toString() ??
          raw['background']?.toString() ??
          raw['context']?.toString() ??
          raw['scenario']?.toString() ??
          raw['scenarioText']?.toString(),
      choices: choices,
      correctLabels: correctLabels,
      choiceRationales: rationales,
      explanation: raw['explanation']?.toString(),
      questionKind: kind,
      requiredCorrectCount: requiredCorrectCount,
      difficulty: difficulty,
      domain: domain,
      major: major,
      mid: raw['mid']?.toString(),
      topic: raw['topic']?.toString(),
      sourceType: 'ai',
      sourceTag: fixedSourceTag,
      imagePath: (imagePath ?? '').trim().isEmpty ? null : imagePath,
      imageRequired: imageRequired,
    );
  }

  /// 生成結果を Map として返す（practice / mock 互換）
  static Future<Map<String, dynamic>> fetchQuestion({
    required String difficulty,
    required String domain,
    required String major,
    String? mid,
    String? scenarioAspect,
  }) async {
    final swTotal = Stopwatch()..start();

    int tSettingsMs = 0;
    int tPickMs = 0;
    int tPromptMs = 0;
    int tHttpMs = 0;
    int tDecodeMs = 0;
    int tParseMs = 0;
    int tPostMs = 0;

    int lenSystem = 0;
    int lenUser = 0;
    int lenRequestBody = 0;
    int lenResponseBody = 0;
    int lenContent = 0;

    String resolvedMidForLog = '';
    String topicForLog = '';

    // ===== APIキー / モデル取得 =====
    final apiKey = await SettingsService.getApiKey();
    final model = await SettingsService.getModel() ?? 'gpt-4o-mini';

    if (apiKey == null || apiKey.isEmpty) {
      throw StateError('OpenAI APIキーが未設定です。設定画面から入力してください。');
    }

    // ===== 出題形式決定 =====
    final swSettings = Stopwatch()..start();

    final options = await QuestionGenerationOptionsResolver.resolve();

    swSettings.stop();
    tSettingsMs = swSettings.elapsedMilliseconds;

    debugPrint(
      '[log] [SETTINGS] ChoiceMode=${options.choiceMode} | '
          '5択確率=${options.probFiveChoice}% | '
          '複数選択確率=${options.probMultiple}% | '
          '誤答確率=${options.probIncorrect}%',
    );

    debugPrint(
      '[log] [QS] desiredChoiceCount=${options.desiredChoiceCount} | '
          'requiredCorrectCount=${options.requiredCorrectCount} | '
          'desiredKind=${options.desiredKind}',
    );

    // ===== mid / topic 決定 =====
    final swPick = Stopwatch()..start();

    final topicResolution = await QuestionTopicResolver.resolve(
      domain: domain,
      major: major,
      mid: mid,
    );

    swPick.stop();
    tPickMs = swPick.elapsedMilliseconds;

    final resolvedMid = topicResolution.resolvedMid;
    final topic = topicResolution.topic;

    resolvedMidForLog = (resolvedMid ?? '').trim();
    topicForLog = (topic ?? '').trim();

    // ===== プロンプト生成 =====
    final swPrompt = Stopwatch()..start();

    final system = PromptBuilder.buildSystemPrompt(
      desiredKind: options.desiredKind,
      desiredChoiceCount: options.desiredChoiceCount,
      requiredCorrectCount: options.requiredCorrectCount,
    );

    final user = PromptBuilder.buildUserPrompt(
      difficulty: difficulty,
      domain: domain,
      major: major,
      mid: resolvedMid,
      topic: topic,
      scenarioAspect: scenarioAspect,
      desiredKind: options.desiredKind,
      desiredChoiceCount: options.desiredChoiceCount,
      requiredCorrectCount: options.requiredCorrectCount,
    );

    swPrompt.stop();
    tPromptMs = swPrompt.elapsedMilliseconds;

    lenSystem = system.length;
    lenUser = user.length;

    // ===== LLM 呼び出し =====
    final swHttp = Stopwatch()..start();

    String content = '';

    try {
      final result = await _chatClient.createJsonObjectCompletion(
        apiKey: apiKey,
        model: model,
        system: system,
        user: user,
        temperature: 0.4,
      );

      swHttp.stop();
      tHttpMs = swHttp.elapsedMilliseconds;

      lenRequestBody = result.requestBody.length;
      lenResponseBody = result.responseBody.length;

      content = result.content;
      lenContent = content.length;
    } on OpenAiHttpException catch (e) {
      swHttp.stop();
      tHttpMs = swHttp.elapsedMilliseconds;

      swTotal.stop();

      final bodyPreview = _firstLines(e.body, maxChars: 240);

      debugPrint(
        '[perf] [QS] FAIL status=${e.statusCode} total=${swTotal.elapsedMilliseconds}ms | '
            'settings=${tSettingsMs}ms pick=${tPickMs}ms prompt=${tPromptMs}ms http=${tHttpMs}ms',
      );

      debugPrint('[perf] [QS] FAIL response(head)=$bodyPreview');

      throw StateError('OpenAIリクエスト失敗 (${e.statusCode}): ${e.body}');
    }

    // ===== content 抽出ログ =====
    final swDecode = Stopwatch()..start();
    swDecode.stop();
    tDecodeMs = swDecode.elapsedMilliseconds;

    debugPrint('[log] [QS] raw content (head) = ${_firstLines(content)}');

    // ===== LLMレスポンス解析 =====
    final swParse = Stopwatch()..start();

    final parsed = ResponseParser.parseContentToQuestion(
      content,
      difficulty: difficulty,
      domain: domain,
      major: major,
      mid: resolvedMid,
      topic: topic,
    );

    swParse.stop();
    tParseMs = swParse.elapsedMilliseconds;

    // ===== 最終安全化 =====
    final swPost = Stopwatch()..start();

    final out = QuestionPostProcessor.process(
      parsed: parsed,
      desiredKind: options.desiredKind,
      requiredCorrectCount: options.requiredCorrectCount,
    );

    swPost.stop();
    tPostMs = swPost.elapsedMilliseconds;

    debugPrint(
      '[log] [QS] parsed => kind=${out['questionKind']}, '
          'choices=${(out['choices'] as Map?)?.keys.join(',') ?? ''} '
          '(len=${(out['choices'] as Map?)?.length ?? 0}), '
          'correct=${(out['correctAnswers'] as List?)?.join(',') ?? ''}',
    );

    swTotal.stop();

    int outJsonLen;

    try {
      outJsonLen = jsonEncode(out).length;
    } catch (_) {
      outJsonLen = -1;
    }

    debugPrint(
      '[perf] [QS] OK total=${swTotal.elapsedMilliseconds}ms | '
          'settings=${tSettingsMs}ms pick=${tPickMs}ms prompt=${tPromptMs}ms '
          'http=${tHttpMs}ms decode=${tDecodeMs}ms parse=${tParseMs}ms post=${tPostMs}ms',
    );

    debugPrint(
      '[perf] [QS] meta model=$model diff=$difficulty domain=$domain major=$major '
          'mid=${resolvedMidForLog.isEmpty ? "-" : resolvedMidForLog} '
          'topic=${topicForLog.isEmpty ? "-" : topicForLog} '
          'kind=${options.desiredKind} choices=${options.desiredChoiceCount} '
          'correctN=${options.requiredCorrectCount}',
    );

    debugPrint(
      '[perf] [QS] size system=$lenSystem user=$lenUser reqBody=$lenRequestBody '
          'resBody=$lenResponseBody content=$lenContent outJson=$outJsonLen',
    );

    return out;
  }

  static String _firstLines(String s, {int maxChars = 300}) {
    final t = s.replaceAll('\n', ' ');
    return (t.length <= maxChars) ? t : '${t.substring(0, maxChars)}...';
  }
}

// lib/questioning/services/question_topic_resolver.dart

import '../../data/hisshu_categories.dart';
import '../models/category_models.dart';
import '../repositories/category_repository.dart';
import 'topic_picker.dart';

class QuestionTopicResolution {
  final String? resolvedMid;
  final String? topic;

  const QuestionTopicResolution({
    required this.resolvedMid,
    required this.topic,
  });
}

class QuestionTopicResolver {
  const QuestionTopicResolver._();

  static Future<QuestionTopicResolution> resolve({
    required String domain,
    required String major,
    String? mid,
  }) async {
    final bool isHisshu = domain == kHisshuCategory;

    if (isHisshu) {
      return _resolveHisshu(
        major: major,
      );
    }

    return _resolveGeneral(
      domain: domain,
      major: major,
      mid: mid,
    );
  }

  static Future<QuestionTopicResolution> _resolveHisshu({
    required String major,
  }) async {
    final DomainCategory tree = CategoryRepository.buildHisshuTree();

    final MajorCategory majorNode = tree.majors.firstWhere(
          (m) => m.id == major,
      orElse: () => tree.majors.isNotEmpty
          ? tree.majors.first
          : MajorCategory(id: major, label: major, mids: const []),
    );

    final mids = majorNode.mids.map((m) => m.id).toList();
    if (mids.isEmpty) {
      return const QuestionTopicResolution(
        resolvedMid: null,
        topic: null,
      );
    }

    final resolvedMid =
    await TopicPicker.pickHisshuMidForMajor(majorNode.id, mids);

    final midNode = _findMidNode(majorNode, resolvedMid);
    final topics = (midNode?.topics ?? const <Topic>[])
        .map((t) => t.label)
        .where((s) => s.trim().isNotEmpty)
        .toList();

    String? topic;
    if (topics.isNotEmpty && resolvedMid.isNotEmpty) {
      topic = await TopicPicker.pickTopic(
        domain: kHisshuCategory,
        major: majorNode.id,
        mid: resolvedMid,
        topics: topics,
      );
    }

    return QuestionTopicResolution(
      resolvedMid: resolvedMid,
      topic: topic,
    );
  }

  static Future<QuestionTopicResolution> _resolveGeneral({
    required String domain,
    required String major,
    String? mid,
  }) async {
    final DomainCategory tree = CategoryRepository.buildGeneralDomainTree(domain);

    final MajorCategory majorNode = tree.majors.firstWhere(
          (m) => m.id == major,
      orElse: () => tree.majors.isNotEmpty
          ? tree.majors.first
          : MajorCategory(id: major, label: major, mids: const []),
    );

    String? resolvedMid;
    if (mid != null && mid.trim().isNotEmpty) {
      resolvedMid = mid.trim();
    } else {
      final mids = majorNode.mids.map((m) => m.id).toList();
      if (mids.isNotEmpty) {
        resolvedMid = await TopicPicker.pickMidForMajor(
          domain: domain,
          major: majorNode.id,
          mids: mids,
        );
      }
    }

    if (resolvedMid == null || resolvedMid.isEmpty) {
      return const QuestionTopicResolution(
        resolvedMid: null,
        topic: null,
      );
    }

    final midNode = _findMidNode(majorNode, resolvedMid);
    final topics = (midNode?.topics ?? const <Topic>[])
        .map((t) => t.label)
        .where((s) => s.trim().isNotEmpty)
        .toList();

    String? topic;
    if (topics.isNotEmpty) {
      topic = await TopicPicker.pickTopic(
        domain: domain,
        major: majorNode.id,
        mid: resolvedMid,
        topics: topics,
      );
    }

    return QuestionTopicResolution(
      resolvedMid: resolvedMid,
      topic: topic,
    );
  }

  static MidCategory? _findMidNode(MajorCategory majorNode, String? midId) {
    if (majorNode.mids.isEmpty) return null;

    if (midId != null && midId.isNotEmpty) {
      for (final m in majorNode.mids) {
        if (m.id == midId) {
          return m;
        }
      }
    }

    return majorNode.mids.first;
  }
}

// lib/questioning/services/response_parser.dart
import 'dart:convert';
import 'package:flutter/foundation.dart';

class ResponseParser {
  static const bool _debug = true; // 一旦 true にして挙動を追いやすく

  /// content(JSON文字列) → 画面がそのまま使える Map に整形
  static Map<String, dynamic> parseContentToQuestion(
      String content, {
        required String difficulty,
        required String domain,
        required String major,
        String? mid,
        String? topic,
      }) {
    final Map<String, dynamic> meta = {
      'difficulty': difficulty,
      'domain': domain,
      'major': major,
      if (mid != null) 'mid': mid,
      if (topic != null) 'topic': topic,
    };

    // ===== JSON 取り出し =====
    Map<String, dynamic> obj;
    try {
      obj = jsonDecode(_stripBom(content).trim()) as Map<String, dynamic>;
    } catch (e) {
      _debugPrint('decode failed (direct): $e');
      final extracted = _extractJsonObject(content);
      obj = jsonDecode(_stripBom(extracted)) as Map<String, dynamic>;
    }

    // ログ：生の correctAnswers
    _debugPrint('raw correctAnswers field = ${obj['correctAnswers']}');

    // ===== 基本構造の取得 =====
    final String question = (obj['question'] ?? '').toString().trim();
    final Map<String, String> choices = _normalizeChoices(obj['choices']);
    final List<String> correctAnswers =
    _normalizeCorrectAnswers(obj, choices.keys.toList());
    final String kind =
    (obj['questionKind'] ?? obj['kind'] ?? 'single').toString();
    final String explanation = (obj['explanation'] ?? '').toString();
    final Map<String, String>? rationales =
    _normalizeRationales(obj['rationales'] ?? obj['reasons'] ?? obj['rationale']);

    // ===== 整合性チェック =====
    final orderedKeys =
    ['A', 'B', 'C', 'D', 'E'].where(choices.containsKey).toList();

    final Map<String, String> orderedChoices = {
      for (final k in orderedKeys) k: choices[k]!,
    };

    // correctAnswers が choices に存在しないラベルを持っていたら落とす
    final filteredCorrect =
    correctAnswers.where(orderedChoices.containsKey).toList();

    // フォールバック：正答が空のときや choices が空のときの保険
    final safeCorrect = filteredCorrect.isNotEmpty
        ? filteredCorrect
        : (orderedChoices.isNotEmpty ? [orderedKeys.first] : <String>[]);

    _debugPrint('--- ResponseParser ---');
    _debugPrint(
        'kind=$kind  choices=${orderedChoices.keys}  safeCorrect=$safeCorrect');

    return {
      'question': question,
      'choices': orderedChoices,
      'correctAnswers': safeCorrect,
      'explanation': explanation,
      'rationales': rationales,
      'questionKind': kind,
      'meta': meta,
    };
  }

  // ------------------------------------------------------------
  // 正規化ヘルパ
  // ------------------------------------------------------------

  static Map<String, String> _normalizeChoices(dynamic raw) {
    if (raw is List) {
      final Map<String, String> out = {};
      int auto = 0;
      for (final e in raw) {
        final s = e.toString().trim();
        final m = RegExp(r'^([A-E])[\.\)]\s*(.*)$').firstMatch(s);
        if (m != null) {
          out[m.group(1)!] = (m.group(2) ?? '').trim();
        } else {
          final label = String.fromCharCode('A'.codeUnitAt(0) + auto);
          out[label] = s;
          auto++;
        }
      }
      return out;
    }

    if (raw is Map) {
      // ラベル順 A..E のみ採用（きれいに並べる）
      final order = ['A', 'B', 'C', 'D', 'E'];
      final Map<String, String> out = {};
      for (final k in order) {
        final v = raw[k];
        if (v == null) continue;
        final s = v.toString().trim();
        if (s.isEmpty) continue;
        out[k] = s;
      }
      // 任意キーしかない場合のフォールバック（順は維持しないが落ちない）
      if (out.isEmpty) {
        raw.forEach((k, v) {
          final kk = k.toString().trim();
          final vv = v.toString().trim();
          if (kk.isNotEmpty && vv.isNotEmpty) out[kk] = vv;
        });
      }
      return out;
    }

    return {};
  }

  static List<String> _normalizeCorrectAnswers(
      Map<String, dynamic> obj,
      List<String> orderedLabels,
      ) {
    final raw = obj['correctAnswers'] ?? obj['answer'] ?? obj['answers'];
    final Set<String> acc = {};

    void addOne(dynamic v) {
      final lab = _toLabel(v);
      if (lab != null) acc.add(lab);
    }

    if (raw is List) {
      for (final v in raw) addOne(v);
    } else if (raw != null) {
      addOne(raw);
    }

    // ラベル順で整列し、存在しないラベルは除外
    final keep = acc.where(orderedLabels.contains).toList()
      ..sort((a, b) =>
          orderedLabels.indexOf(a).compareTo(orderedLabels.indexOf(b)));

    _debugPrint('normalized correctAnswers = $keep');
    return keep;
  }

  static Map<String, String>? _normalizeRationales(dynamic raw) {
    if (raw is Map) {
      return raw
          .map((k, v) => MapEntry(k.toString().trim(), v.toString().trim()));
    }
    return null;
  }

  static String? _toLabel(dynamic v) {
    if (v == null) return null;
    final s = v.toString().trim();
    if (s.isEmpty) return null;

    // 数値(0/1/2/3/4) or (1/2/3/4/5) → A..E
    final asInt = int.tryParse(s);
    if (asInt != null) {
      final idx = (asInt >= 1 && asInt <= 5) ? asInt - 1 : asInt; // 1-originにも対応
      if (idx >= 0 && idx < 5) {
        return String.fromCharCode('A'.codeUnitAt(0) + idx);
      }
    }

    final first = s[0].toUpperCase();
    if ('ABCDE'.contains(first)) return first;
    return null;
  }

  // ------------------------------------------------------------
  // JSON抽出（```json ... ```対応）
  // ------------------------------------------------------------
  static String _extractJsonObject(String s) {
    final text = _stripBom(s);

    // フェンス（```json ... ``` or ``` ... ```）を最優先
    final fence = RegExp(
      r'```+\s*json\s*([\s\S]*?)```+|```+\s*([\s\S]*?)```+',
      multiLine: true,
      caseSensitive: false,
    );
    final fm = fence.firstMatch(text);
    final body = fm != null ? (fm.group(1) ?? fm.group(2) ?? '') : text;

    final start = body.indexOf('{');
    if (start < 0) return '{}';

    int depth = 0;
    for (int i = start; i < body.length; i++) {
      final ch = body[i];
      if (ch == '{') {
        depth++;
      } else if (ch == '}') {
        depth--;
        if (depth == 0) {
          return body.substring(start, i + 1);
        }
      }
    }
    return '{}';
  }

  static String _stripBom(String s) {
    if (s.isEmpty) return s;
    const bom = '\u{FEFF}';
    return s.startsWith(bom) ? s.substring(1) : s;
  }

  static void _debugPrint(String msg) {
    if (_debug) debugPrint('[ResponseParser] $msg');
  }
}

// lib/questioning/services/topic_picker.dart

import 'dart:math';
import 'package:shared_preferences/shared_preferences.dart';

/// 3階層対応の袋方式ローテータ
/// - 同じ「分野>大項目>中項目」内では、小項目を引き切るまで重複しにくい
/// - 中項目未選択の時は「分野>大項目」内の中項目を均等ローテーション
class TopicPicker {
  TopicPicker._();

  /// 小項目ピック（分野>大項目>中項目）
  static Future<String> pickTopic({
    required String domain,
    required String major,
    required String mid,
    required List<String> topics,
  }) {
    return _nextFromBag('topic::$domain::$major::$mid', topics);
  }

  /// 中項目ピック（一般/状況設定：UI未選択時）
  static Future<String> pickMidForMajor({
    required String domain,
    required String major,
    required List<String> mids,
  }) {
    return _nextFromBag('general-mid::$domain::$major', mids);
  }

  /// 必修：大項目から中項目ピック（従来互換）
  static Future<String> pickHisshuMidForMajor(String major, List<String> mids) {
    return _nextFromBag('hisshu-mid::$major', mids);
  }

  /// 任意の袋キーで items を均等ローテーション
  static Future<String> _nextFromBag(String key, List<String> items) async {
    if (items.isEmpty) {
      throw StateError('TopicPicker: items is empty for key=$key');
    }
    final prefs = await SharedPreferences.getInstance();
    final rnd = Random();

    // 保存済み袋
    final raw = prefs.getStringList(key) ?? const <String>[];
    // 現行リストと突き合わせ（定義変更に強い）
    final inBag = raw.where((e) => items.contains(e)).toList();

    List<String> bag = inBag.isEmpty ? (List<String>.from(items)..shuffle(rnd)) : inBag;

    final picked = bag.removeAt(0);
    await prefs.setStringList(key, bag);
    return picked;
  }

  /// 設定画面から呼ぶ想定のリセット
  static Future<void> resetAll({List<String> keys = const <String>[]}) async {
    final prefs = await SharedPreferences.getInstance();
    if (keys.isEmpty) {
      for (final k in prefs.getKeys()) {
        if (k.startsWith('topic::') || k.startsWith('general-mid::') || k.startsWith('hisshu-mid::')) {
          await prefs.remove(k);
        }
      }
    } else {
      for (final k in keys) {
        await prefs.remove(k);
      }
    }
  }
}
